SELECT p2.name FROM Person p1, friend f, Person p2 WHERE MATCH(p1-(f)->p2);
SELECT p1.name FROM Person p1, friend f, Person p2 WHERE MATCH(p2<-(f)-p1);
SELECT 1 FROM Person p1, friend f1, Person p2, friend f2, Person p3 WHERE MATCH(p1-(f1)->p2 AND p2-(f2)->p3);
SELECT 1 FROM Person p1, friend f1, Person p2, friend f2, Person p3 WHERE MATCH(p1-(f1)->p2<-(f2)-p3);

SELECT p1.name, STRING_AGG(p2.name, '->') WITHIN GROUP (GRAPH PATH) AS path
FROM Person AS p1, friend FOR PATH AS f, Person FOR PATH AS p2
WHERE MATCH(SHORTEST_PATH(p1(-(f)->p2)+));
SELECT p1.name, LAST_VALUE(p2.name) WITHIN GROUP (GRAPH PATH) AS last
FROM Person AS p1, friend FOR PATH AS f, Person FOR PATH AS p2
WHERE MATCH(SHORTEST_PATH(p1(-(f)->p2){1,3}));
SELECT 1 FROM Person AS p1, friend FOR PATH AS f, Person FOR PATH AS p2
WHERE MATCH(SHORTEST_PATH((p2<-(f)-)+p1));

SELECT 1 FROM Person AS p1, friend FOR PATH AS f1, Person FOR PATH AS p2,
  Person AS p3, friend FOR PATH AS f2, Person FOR PATH AS p4
WHERE MATCH(SHORTEST_PATH(p1(-(f1)->p2)+) AND SHORTEST_PATH(p3(-(f2)->p4)+) AND LAST_NODE(p2) = LAST_NODE(p4));

